def subtotal(items):
    return sum(price * qty for price, qty in items)

def apply_tax(amount, rate=0.1):
    return amount + amount * rate

def total_price_refactored(items):
    return apply_tax(subtotal(items))

def total_price(items):
    subtotal_amount = sum(price * qty for price, qty in items)
    tax = subtotal_amount * 0.1
    return subtotal_amount + tax

items = [(10, 2), (5, 3)]
print(f"Total: {total_price(items):.2f}")
print(f"Refactored total: {total_price_refactored(items):.2f}")
